def compute(vars):
    net_revenue_decrease = vars["v2"] - vars["v3"]
    nuclear_price_decrease = -vars["v1"]

    if net_revenue_decrease == 0:
        return None

    percentage = nuclear_price_decrease / net_revenue_decrease * 100

    return {
        "value": percentage,
        "trace": {
            "nuclear_price_decrease": nuclear_price_decrease,
            "net_revenue_decrease": net_revenue_decrease,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
